                        addNoticeOnce(
                            characterIndex,
                            "corrected:"+decision.action,
                            "åµæ¸¬åˆ°ã€Œ"+decision.skill.name+"ã€è¢«éŒ¯èª¤æ’æˆæ™®é€šæ”»æ“Šï¼Œå·²è‡ªå‹•æ ¡æ­£ä¸¦æ–½æ”¾æŠ€èƒ½ã€‚"
                        );
