            monster.maxHP=Math.max(1,Number(shield.baseMaxHP)||1);
            monster.hp=Math.min(monster.maxHP,currentHp);
            monster.v141Shield=null;
            monster.activeBuffs=(monster.activeBuffs||[]).filter(buff=>buff!==shield&&buff.type!=="shield");
