        overlay.setAttribute("aria-label","å®ˆé—œè€…å°è©±ï¼Œé»æ“Šç¹¼çºŒ");
        overlay.innerHTML='<small>'+escapeHtml(speaker)+'</small><b></b><span>é»æ“Šç©ºç™½è™•ç¹¼çºŒã€€'+(index+1)+' / '+lines.length+'</span>';
        const text=overlay.querySelector("b");
