                abyssState.phase="portal";
                abyssState.message="å¯¶ç®±å·²é–‹å•Ÿã€‚è«‹é»æ“Šä¸Šæ–¹å‚³é€é»å‰å¾€ä¸‹ä¸€å±¤ã€‚";
